-- TPC-DS Test_Query Query 487
-- Based on: query63.tpl (medium)
-- Variation: 70

 select  * from (select i_manager_id ,sum(ss_sales_price) sum_sales ,avg(sum(ss_sales_price)) over (partition by i_manager_id) avg_monthly_sales from item ,store_sales ,date_dim ,store where ss_item_sk = i_item_sk and ss_sold_date_sk = d_date_sk and ss_store_sk = s_store_sk and d_month_seq in (6,19+1,18+2,25+2,35+3,28+4,36+4,46+9,51+10,98+10,38+9,80+11) and ((    i_category in ('Books','Children','Electronics') and i_class in ('personal','portable','reference','self-help') and i_brand in ('scholaramalgamalg #15','scholaramalgamalg #8', 'exportiunivamalg #8','scholaramalgamalg #8')) or(    i_category in ('Women','Music','Men') and i_class in ('accessories','classical','fragrances','pants') and i_brand in ('amalgimporto #1','edu packscholar #3','exportiimporto #1', 'importoamalg #1'))) group by i_manager_id, d_moy) tmp1 where case when avg_monthly_sales > 1 then abs (sum_sales - avg_monthly_sales) / avg_monthly_sales else null end > 0.2 order by i_manager_id ,avg_monthly_sales ,sum_sales limit 98;
